package com.nextfeet.nextfeet.service; import java.util.*; import org.springframework.stereotype.Service; import com.nextfeet.nextfeet.model.Oferta; import com.nextfeet.nextfeet.repository.OfertaDAO; @Service public class OfertaServiceImpl implements OfertaService {private final OfertaDAO dao; public OfertaServiceImpl(OfertaDAO dao){this.dao=dao;} public List<Oferta> listar(){return dao.listar();} public void crear(Oferta o){dao.crear(o);} public void actualizar(Oferta o){dao.actualizar(o);} public void desactivar(Integer id){dao.desactivar(id);}}